     1→/**
     2→ * Message Service
     3→ *
     4→ * Manages WhatsApp message CRUD operations using Sequelize ORM.
     5→ * Handles incoming and outgoing messages with soft deletes (paranoid mode).
     6→ *
     7→ * Phase D: Sequelize implementation
     8→ */
     9→
    10→import { Lead, User, WhatsAppLine, ConversationAssignment } from '../models/sequelize/associations.js';
    11→import Message  from '../models/sequelize/Message.js';
    12→import { Op } from 'sequelize';
    13→import sequelize from '../config/sequelize.js';
    14→
    15→class MessageService {
    16→  /**
    17→   * Save an incoming message from WhatsApp webhook
    18→   * @param {Object} messageData - Message information
    19→   * @returns {Promise<Object>} Created message
    20→   */
    21→  async saveIncomingMessage(messageData) {
    22→    try {
    23→      // Find the most recent conversation_assignment for this phone_number + line_id
    24→      // This ensures the reply goes to the last user who contacted this number
    25→      const latestAssignment = await ConversationAssignment.findOne({
    26→        where: {
    27→          phone_number: messageData.phone_number,
    28→          line_id: messageData.line_id
    29→        },
    30→        order: [['assigned_at', 'DESC']]
    31→      });
    32→
    33→      const message = await Message.create({
    34→        line_id: messageData.line_id,
    35→        lead_id: messageData.lead_id,
    36→        company_id: messageData.company_id, // Required for company segmentation
    37→        phone_number: messageData.phone_number,
    38→        message_content: messageData.message_content || '',
    39→        message_type: messageData.message_type || 'text',
    40→        direction: 'incoming',
    41→        status: 'received',
    42→        file_url: messageData.file_url || null,
    43→        meta_message_id: messageData.meta_message_id,
    44→        reply_to_message_id: messageData.reply_to_message_id || null,
    45→        campaign_id: messageData.campaign_id || null,
    46→        assigned_user_id: messageData.assigned_user_id || null,
    47→        assigned_user_ids: messageData.assigned_user_ids || null, // Array of assigned agents
    48→        conversation_assignment_id: latestAssignment ? latestAssignment.id : null, // Assign to latest conversation
    49→        interactive_type: messageData.interactive_type || null,
    50→        interactive_data: messageData.interactive_data || null,
    51→      });
    52→
    53→      return message.toJSON();
    54→    } catch (error) {
    55→      // Handle duplicate meta_message_id (webhook retries)
    56→      if (error.name === 'SequelizeUniqueConstraintError') {
    57→        const existing = await Message.findOne({
    58→          where: { meta_message_id: messageData.meta_message_id },
    59→        });
    60→        return existing ? existing.toJSON() : null;
    61→      }
    62→      throw new Error(`Error saving incoming message: ${error.message}`);
    63→    }
    64→  }
    65→
    66→  /**
    67→   * Save an outgoing message sent by an agent
    68→   * @param {Object} messageData - Message information
    69→   * @returns {Promise<Object>} Created message
    70→   */
    71→  async saveOutgoingMessage(messageData) {
    72→    try {
    73→      // Get or create conversation assignment for manual messages
    74→      // Each user gets their own independent conversation with the same number
    75→      let conversationAssignmentId = null;
    76→      let campaignId = messageData.campaign_id || null;
    77→      let assignedUserIds = null;
    78→
    79→      if (messageData.user_id) {
    80→        // First, try to find existing assignment to get campaign context
    81→        let existingAssignment = await ConversationAssignment.findOne({
    82→          where: {
    83→            phone_number: messageData.phone_number,
    84→            line_id: messageData.line_id,
    85→            assigned_user_id: messageData.user_id
    86→          }
    87→        });
    88→
    89→        // If exists, use its campaign_id (unless explicitly provided)
    90→        if (existingAssignment && !messageData.campaign_id) {
    91→          campaignId = existingAssignment.campaign_id;
    92→        }
    93→
    94→        const [conversationAssignment, created] = await ConversationAssignment.findOrCreate({
    95→          where: {
    96→            phone_number: messageData.phone_number,
    97→            line_id: messageData.line_id,
    98→            assigned_user_id: messageData.user_id
    99→          },
   100→          defaults: {
   101→            assigned_at: new Date(),
   102→            assigned_by_user_id: messageData.user_id,
   103→            campaign_id: campaignId
   104→          }
   105→        });
   106→
   107→        // CRITICAL: Update assigned_at every time this user sends a message
   108→        // This ensures replies go to the LAST user who contacted this number
   109→        if (!created) {
   110→          await conversationAssignment.update({
   111→            assigned_at: new Date()
   112→            // Keep existing campaign_id - don't overwrite
   113→          });
   114→        }
   115→
   116→        conversationAssignmentId = conversationAssignment.id;
   117→        assignedUserIds = [messageData.user_id];
   118→      }
   119→
   120→      const message = await Message.create({
   121→        line_id: messageData.line_id,
   122→        lead_id: messageData.lead_id,
   123→        company_id: messageData.company_id, // Required for company segmentation
   124→        user_id: messageData.user_id,
   125→        template_id: messageData.template_id || null,
   126→        phone_number: messageData.phone_number,
   127→        message_content: messageData.message_content || '',
   128→        message_type: messageData.message_type || 'text',
   129→        direction: 'outgoing',
   130→        status: messageData.status || 'pending',
   131→        file_url: messageData.file_url || null,
   132→        is_mass_campaign: messageData.is_mass_campaign || false,
   133→        meta_message_id: messageData.meta_message_id || null,
   134→        reply_to_message_id: messageData.reply_to_message_id || null,
   135→        campaign_id: campaignId, // Include campaign_id from conversation context
   136→        campaign_name: messageData.campaign_name || null,
   137→        assigned_user_id: messageData.user_id,
   138→        assigned_user_ids: assignedUserIds,
   139→        conversation_assignment_id: conversationAssignmentId, // Link to conversation
   140→        interactive_type: messageData.interactive_type || null,
   141→        interactive_data: messageData.interactive_data || null,
   142→      });
   143→
   144→      return message.toJSON();
   145→    } catch (error) {
   146→      throw new Error(`Error saving outgoing message: ${error.message}`);
   147→    }
   148→  }
   149→
   150→  /**
   151→   * Update message status (for delivery tracking)
   152→   * @param {string} metaMessageId - Meta's message ID
   153→   * @param {string} status - New status (sent, delivered, read, failed)
   154→   * @returns {Promise<Object|null>} Updated message or null
   155→   */
   156→  async updateMessageStatus(metaMessageId, status) {
   157→    try {
   158→      const message = await Message.findOne({
   159→        where: { meta_message_id: metaMessageId },
   160→      });
   161→
   162→      if (!message) {
   163→        return null;
   164→      }
   165→
   166→      await message.update({ status });
   167→      return message.toJSON();
   168→    } catch (error) {
   169→      throw new Error(`Error updating message status: ${error.message}`);
   170→    }
   171→  }
   172→
   173→  /**
   174→   * Get conversation messages (paginated with cursor)
   175→   * @param {Object} options - Query options
   176→   * @param {string} options.phone_number - Customer phone number
   177→   * @param {number} options.line_id - WhatsApp line ID
   178→   * @param {Date} [options.cursor] - Timestamp cursor for pagination
   179→   * @param {number} [options.limit=50] - Messages per page
   180→   * @returns {Promise<Object>} Messages array and pagination info
   181→   */
   182→  async getConversationMessages(options) {
   183→    try {
   184→      const {
   185→        phone_number,
   186→        line_id,
   187→        cursor,
   188→        limit = 50,
   189→        conversation_assignment_id = null,
   190→      } = options;
   191→
   192→
   193→      const where = {
   194→        phone_number,
   195→        line_id,
   196→      };
   197→
   198→      // Filter by conversation_assignment_id if provided (for agents)
   199→      // Admins don't have this filter, so they see all messages for this phone_number + line_id
   200→      if (conversation_assignment_id !== null) {
   201→        where.conversation_assignment_id = conversation_assignment_id;
   202→        console.log('[MessageService] Filtering messages by conversation_assignment_id:', conversation_assignment_id);
   203→      } else {
