   289→   * @param {string|null} [status=null] - Filter by lead status
   290→   * @returns {Promise<Array>} Conversations with last message info
   291→   */
   292→  async getRecentConversations(lineId, limit = 50, userId = null, offset = 0, search = null, status = null) {
   293→    try {
   294→      // If userId is provided, filter conversations by assignment
   295→      // Use conversation_assignments as source of truth for ownership
   296→      const replacements = [];
   297→
   298→      let query = '';
   299→
   300→      if (userId) {
   301→        // For agents: Support both new (conversation_assignment_id) and legacy (assigned_user_id) systems
   302→        query = `
   303→          SELECT
   304→            m1.phone_number,
   305→            m1.line_id,
   306→            m1.created_at as last_message_at,
   307→            m1.message_content as last_message,
   308→            m1.direction as last_message_direction,
   309→            m1.campaign_id,
   310→            m1.campaign_name,
   311→            COALESCE(ca.assigned_user_id, m1.assigned_user_id) as assigned_user_id,
   312→            m1.assigned_user_ids,
   313→            ca.campaign_id as conversation_campaign_id,
   314→            ca.id as conversation_assignment_id,
   315→            l.id as lead_id,
   316→            l.name as lead_name,
   317→            l.status as lead_status,
   318→            COUNT(CASE WHEN m2.direction = 'incoming' AND m2.status = 'received' THEN 1 END) as unread_count
   319→          FROM messages m1
   320→          LEFT JOIN conversation_assignments ca
   321→            ON m1.conversation_assignment_id = ca.id
   322→          LEFT JOIN leads l
   323→            ON m1.phone_number COLLATE utf8mb4_unicode_ci = l.phone_number COLLATE utf8mb4_unicode_ci
   324→          LEFT JOIN messages m2
   325→            ON (
   326→              (m2.conversation_assignment_id IS NOT NULL AND m2.conversation_assignment_id = m1.conversation_assignment_id)
   327→              OR (m2.conversation_assignment_id IS NULL AND m2.phone_number COLLATE utf8mb4_unicode_ci = m1.phone_number COLLATE utf8mb4_unicode_ci AND m2.line_id = m1.line_id)
   328→            )
   329→            AND m2.deleted_at IS NULL
   330→          WHERE m1.deleted_at IS NULL
   331→            AND ca.id IS NOT NULL
   332→            AND ca.assigned_user_id = ?
   333→        `;
   334→        replacements.push(userId);
   335→
   336→        // Add line filter
   337→        if (lineId !== null && lineId !== undefined) {
   338→          query += ` AND m1.line_id = ?`;
   339→          replacements.push(lineId);
   340→        }
   341→
   342→        // Get the last message for each conversation_assignment_id
   343→        query += `
   344→          AND m1.id = (
   345→            SELECT MAX(id)
   346→            FROM messages m_sub
