   360→            m1.campaign_id,
   361→            m1.campaign_name,
   362→            COALESCE(ca.assigned_user_id, m1.assigned_user_id) as assigned_user_id,
   363→            m1.assigned_user_ids,
   364→            ca.campaign_id as conversation_campaign_id,
   365→            ca.id as conversation_assignment_id,
   366→            l.id as lead_id,
   367→            l.name as lead_name,
   368→            l.status as lead_status,
   369→            COUNT(CASE WHEN m2.direction = 'incoming' AND m2.status = 'received' THEN 1 END) as unread_count
   370→          FROM messages m1
   371→          LEFT JOIN conversation_assignments ca
   372→            ON m1.conversation_assignment_id = ca.id
   373→          LEFT JOIN leads l
   374→            ON m1.phone_number COLLATE utf8mb4_unicode_ci = l.phone_number COLLATE utf8mb4_unicode_ci
   375→          LEFT JOIN messages m2
   376→            ON (
   377→              (m2.conversation_assignment_id IS NOT NULL AND m2.conversation_assignment_id = m1.conversation_assignment_id)
   378→              OR (m2.conversation_assignment_id IS NULL AND m2.phone_number COLLATE utf8mb4_unicode_ci = m1.phone_number COLLATE utf8mb4_unicode_ci AND m2.line_id = m1.line_id)
   379→            )
   380→            AND m2.deleted_at IS NULL
   381→          WHERE m1.deleted_at IS NULL
   382→        `;
   383→
   384→        // Add line filter
   385→        if (lineId !== null && lineId !== undefined) {
   386→          query += ` AND m1.line_id = ?`;
   387→          replacements.push(lineId);
   388→        }
   389→
   390→        // Get the last message for each conversation (new system) or per user+phone_number (legacy system)
   391→        query += `
   392→          AND m1.id = (
   393→            SELECT MAX(id)
   394→            FROM messages m_sub
   395→            WHERE m_sub.deleted_at IS NULL
   396→              AND (
   397→                (m_sub.conversation_assignment_id IS NOT NULL AND m_sub.conversation_assignment_id = m1.conversation_assignment_id)
   398→                OR (
   399→                  m_sub.conversation_assignment_id IS NULL
   400→                  AND m_sub.phone_number COLLATE utf8mb4_unicode_ci = m1.phone_number COLLATE utf8mb4_unicode_ci
   401→                  AND m_sub.line_id = m1.line_id
   402→                  AND COALESCE(m_sub.assigned_user_id, 0) = COALESCE(m1.assigned_user_id, 0)
   403→                )
   404→              )
   405→          )
   406→        `;
   407→      }
   408→
   409→      // Add search filter (applies to both agents and admins)
   410→      if (search) {
   411→        query += ` AND (
   412→          l.name LIKE ?
   413→          OR m1.phone_number LIKE ?
   414→        )`;
   415→        const searchTerm = `%${search}%`;
   416→        replacements.push(searchTerm, searchTerm);
   417→      }
   418→
   419→      // Add status filter (applies to both agents and admins)
   420→      if (status) {
   421→        query += ` AND l.status = ?`;
   422→        replacements.push(status);
   423→      }
   424→
   425→      query += `
