   438→
   439→      // Debug: Check for duplicates by conversation_assignment_id
   440→      const assignmentIds = conversations.map(c => c.conversation_assignment_id).filter(id => id !== null);
   441→      const uniqueAssignmentIds = [...new Set(assignmentIds)];
   442→      if (assignmentIds.length !== uniqueAssignmentIds.length) {
   443→        console.warn('[MessageService] WARNING: Duplicate conversation_assignment_ids found!', {
   444→          total: assignmentIds.length,
