   449→      }
   450→
   451→      // Parse assigned_user_ids from JSON string to array
   452→      return conversations.map(conv => ({
   453→        ...conv,
   454→        assigned_user_ids: conv.assigned_user_ids ?
   455→          (typeof conv.assigned_user_ids === 'string' ? JSON.parse(conv.assigned_user_ids) : conv.assigned_user_ids)
   456→          : null
   457→      }));
   458→    } catch (error) {
   459→      throw new Error(`Error fetching recent conversations: ${error.message}`);
   460→    }
   461→  }
   462→
   463→  /**
   464→   * Soft delete a message
   465→   * @param {number} messageId - Message ID
   466→   * @returns {Promise<boolean>} Success status
   467→   */
   468→  async deleteMessage(messageId) {
