   477→      return true;
   478→    } catch (error) {
   479→      throw new Error(`Error deleting message: ${error.message}`);
   480→    }
   481→  }
   482→
   483→  /**
   484→   * Get message statistics for a line
   485→   * @param {number} lineId - WhatsApp line ID
