import { DataTypes } from 'sequelize';
import sequelize from '../../config/sequelize.js';

const Lead = sequelize.define('Lead', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true,
  },
  company_id: {
    type: DataTypes.INTEGER,
    allowNull: false,
    references: {
      model: 'companies',
      key: 'id',
    },
    validate: {
      notNull: {
        msg: 'Company ID is required',
      },
    },
  },
  phone_number: {
    type: DataTypes.STRING(20),
    allowNull: false,
    unique: true,
    validate: {
      notEmpty: true,
    },
  },
  name: {
    type: DataTypes.STRING(100),
    allowNull: true,
  },
  email: {
    type: DataTypes.STRING(255),
    allowNull: true,
    validate: {
      customEmailValidation(value) {
        // Solo validar si el valor existe y no está vacío
        if (value && value.trim() !== '') {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(value)) {
            throw new Error('Debe ser un correo electrónico válido');
          }
        }
      },
    },
  },
  status: {
    type: DataTypes.ENUM('new', 'contacted', 'qualified', 'converted', 'lost'),
    allowNull: false,
    defaultValue: 'new',
  },
  notes: {
    type: DataTypes.TEXT,
    allowNull: true,
  },
  first_contact_date: {
    type: DataTypes.DATE,
    allowNull: false,
    defaultValue: DataTypes.NOW,
  },
}, {
  tableName: 'leads',
  timestamps: true,
  underscored: true,
  paranoid: true, // Enables soft deletes (deleted_at column)
  indexes: [
    {
      fields: ['company_id'],
      name: 'idx_leads_company',
    },
    {
      unique: true,
      fields: ['phone_number'],
      name: 'idx_leads_phone',
    },
    {
      fields: ['status', 'deleted_at'],
      name: 'idx_leads_status',
    },
    {
      type: 'FULLTEXT',
      fields: ['name'],
      name: 'idx_leads_name_search',
    },
    {
      fields: ['first_contact_date'],
      name: 'idx_leads_first_contact',
    },
    {
      fields: ['deleted_at'],
      name: 'idx_leads_deleted',
    },
  ],
});

export default Lead;

