import TemplateManager from '../../../services/whatsapp/TemplateManager.js';
import TemplateService from '../../../services/TemplateService.js';
import MessageService from '../../../services/MessageService.js';
import { WhatsAppLine, Lead } from '../../../models/sequelize/associations.js';

/**
 * @swagger
 * /api/v1/external/messages/send-template:
 *   post:
 *     summary: Enviar mensaje de plantilla de WhatsApp
 *     description: Envía un mensaje de WhatsApp usando una plantilla aprobada
 *     tags: [External API]
 *     security:
 *       - bearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             $ref: '#/components/schemas/SendTemplateRequest'
 *     responses:
 *       201:
 *         description: Mensaje enviado exitosamente
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/SendTemplateResponse'
 *       400:
 *         description: Datos inválidos o faltantes
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *             examples:
 *               missingFields:
 *                 value:
 *                   success: false
 *                   error: Missing required fields
 *                   message: templateId, lineId, and to are required
 *               invalidPhone:
 *                 value:
 *                   success: false
 *                   error: Invalid phone number
 *                   message: Phone number must be in format 57XXXXXXXXXX (Colombian number with country code)
 *               templateNotApproved:
 *                 value:
 *                   success: false
 *                   error: Template not approved
 *                   message: Template status is 'pending'. Only approved templates can be sent.
 *       401:
 *         description: No autorizado - Credenciales API inválidas
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *       404:
 *         description: Línea o plantilla no encontrada
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Error'
 *             examples:
 *               lineNotFound:
 *                 value:
 *                   success: false
 *                   error: WhatsApp line not found
 *                   message: Line not found, inactive, or does not belong to your company
 *               templateNotFound:
 *                 value:
 *                   success: false
 *                   error: Template not found
 *                   message: The specified template does not exist
 */
export default async function sendTemplateMessage(req, res, next) {
  try {
    const { templateId, lineId, to, variableValues = [], headerParams = {}, buttonParams = [] } = req.body;

    // Validation
    if (!templateId || !lineId || !to) {
      return res.status(400).json({
        success: false,
        error: 'Missing required fields',
        message: 'templateId, lineId, and to are required'
      });
    }

    // Get WhatsApp line and verify it belongs to the company
    const line = await WhatsAppLine.findOne({
      where: {
        id: lineId,
        company_id: req.apiCompany.companyId,
        is_active: true
      }
    });

    if (!line) {
      return res.status(404).json({
        success: false,
        error: 'WhatsApp line not found',
        message: 'Line not found, inactive, or does not belong to your company'
      });
    }

    // Get template and verify it belongs to the line
    const template = await TemplateService.getTemplateById(templateId);

    if (!template) {
      return res.status(404).json({
        success: false,
        error: 'Template not found',
        message: 'The specified template does not exist'
      });
    }

    if (template.line_id !== lineId) {
      return res.status(400).json({
        success: false,
        error: 'Template mismatch',
        message: 'Template does not belong to the specified line'
      });
    }

    if (template.status !== 'approved') {
      return res.status(400).json({
        success: false,
        error: 'Template not approved',
        message: `Template status is '${template.status}'. Only approved templates can be sent.`
      });
    }

    // Normalize phone number
    const normalizedPhone = to.replace(/\D/g, '');

    // Basic validation for Colombian numbers (adjust if needed)
    if (!normalizedPhone.startsWith('57') || normalizedPhone.length < 12) {
      return res.status(400).json({
        success: false,
        error: 'Invalid phone number',
        message: 'Phone number must be in format: 57XXXXXXXXXX (Colombian number with country code)'
      });
    }

    // Get or create lead (filtered by company)
    let lead = await Lead.findOne({
      where: {
        phone_number: `+${normalizedPhone}`,
        company_id: req.apiCompany.companyId
      }
    });

    if (!lead) {
      lead = await Lead.create({
        phone_number: `+${normalizedPhone}`,
        company_id: req.apiCompany.companyId,
        status: 'new',
        first_contact_at: new Date()
      });
    }

    // Send template via Meta API
    const metaResponse = await TemplateManager.sendTemplateMessage({
      line,
      to: `+${normalizedPhone}`,
      template,
      variableValues,
      headerParams,
      buttonParams
    });

    // Build message content with variables replaced
    let messageContent = template.content;

    if (variableValues && variableValues.length > 0) {
      variableValues.forEach((value, index) => {
        const placeholder = `{{${index + 1}}}`;
        messageContent = messageContent.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value);
      });
    }

    // Prepare interactive data if template has buttons
    let interactiveType = null;
    let interactiveData = null;

    if (template.buttons && template.buttons.length > 0) {
      interactiveType = 'button';
      interactiveData = {
        body: messageContent,
        buttons: template.buttons
      };
    }

    // Save message to database (no user_id for API requests)
    const message = await MessageService.saveOutgoingMessage({
      line_id: line.id,
      lead_id: lead.id,
      company_id: req.apiCompany.companyId, // Get company from API authentication
      user_id: null, // API requests don't have a user
      template_id: template.id,
      phone_number: `+${normalizedPhone}`,
      message_content: messageContent,
      message_type: 'template',
      direction: 'outgoing',
      status: 'sent',
      meta_message_id: metaResponse.messages?.[0]?.id,
      is_mass_campaign: false,
      interactive_type: interactiveType,
      interactive_data: interactiveData
    });

    res.status(201).json({
      success: true,
      message: 'Template message sent successfully',
      data: {
        messageId: message.id,
        metaMessageId: metaResponse.messages?.[0]?.id,
        to: `+${normalizedPhone}`,
        templateName: template.name,
        status: 'sent'
      }
    });
  } catch (error) {
    console.error('Error sending template message (API):', error);

    // Handle specific WhatsApp API errors
    if (error.response?.data) {
      return res.status(error.response.status || 500).json({
        success: false,
        error: 'WhatsApp API Error',
        message: error.response.data.error?.message || 'Failed to send message via WhatsApp',
        details: error.response.data
      });
    }

    next(error);
  }
}

