    const existingTables = results.map(row => Object.values(row)[0]);

    for (const table of tables) {
      if (!existingTables.includes(table)) continue;

      const [columns] = await queryInterface.sequelize.query(
        `SHOW COLUMNS FROM ${table} LIKE 'company_id'`
      );

      if (columns.length > 0) continue;

      await queryInterface.addColumn(table, 'company_id', {
        type: Sequelize.INTEGER,
        allowNull: true,
        references: { model: 'companies', key: 'id' },
        onUpdate: 'CASCADE',
        onDelete: 'RESTRICT'
      });

      await queryInterface.addIndex(table, ['company_id'], {
        name: `idx_${table}_company_id`
      });
    }

    for (const table of tables) {
      if (!existingTables.includes(table)) continue;
      await queryInterface.sequelize.query(
        `UPDATE ${table} SET company_id = 1 WHERE company_id IS NULL`
      );
    }

    for (const table of tables) {
      if (!existingTables.includes(table)) continue;
      await queryInterface.changeColumn(table, 'company_id', {
        type: Sequelize.INTEGER,
        allowNull: false,
        references: { model: 'companies', key: 'id' },
        onUpdate: 'CASCADE',
        onDelete: 'RESTRICT'
      });
    }
  },

  async down (queryInterface, Sequelize) {
    const tables = [
      'users', 'phone_lines', 'whatsapp_lines', 'message_templates',
      'leads', 'messages', 'conversation_assignments', 'automation_rules',
      'line_user_assignments', 'phone_line_user_assignments', 'campaign_agent_assignments'
    ];

    for (const table of tables) {
      try { await queryInterface.removeIndex(table, `idx_${table}_company_id`); } catch(e) {}
      try { await queryInterface.removeColumn(table, 'company_id'); } catch(e) {}
    }
  }
};

