import TemplateManager from '../../../services/whatsapp/TemplateManager.js';
import TemplateService from '../../../services/TemplateService.js';
import MessageService from '../../../services/MessageService.js';
import { WhatsAppLine, Lead } from '../../../models/sequelize/associations.js';
import ConversationAssignment from '../../../models/sequelize/ConversationAssignment.js';
import { Op } from 'sequelize';

/**
 * Get phone number variations (with and without + prefix)
 */
function getPhoneVariations(phone) {
  const normalized = phone.replace(/\D/g, '');
  return [`+${normalized}`, normalized];
}

/**
 * POST /api/v1/messages/send-template
 * Send a template message
 * Body:
 *  - templateId: Template ID to send
 *  - lineId: WhatsApp line ID
 *  - to: Recipient phone number
 *  - variableValues: Array of values for template variables (in order)
 *  - headerParams: Object with header parameters (text or media object)
 *  - buttonParams: Array of button parameters for dynamic buttons
 */
export default async function sendTemplate(req, res, next) {
  try {
    const { templateId, lineId, to, variableValues = [], headerParams = {}, headerCaption, buttonParams = [] } = req.body;

    // Validation
    if (!templateId || !lineId || !to) {
      return res.status(400).json({
        success: false,
        error: 'Missing required fields: templateId, lineId, to'
      });
    }

    // Check if agent has access to this line
    if (req.user.role === 'agent') {
      const hasAccess = req.user.assignedLines && req.user.assignedLines.includes(lineId);
      if (!hasAccess) {
        return res.status(403).json({
          success: false,
          error: 'You do not have access to this WhatsApp line'
        });
      }
    }

    // Get template
    const template = await TemplateService.getTemplateById(templateId);

    if (!template) {
      return res.status(404).json({
        success: false,
        error: 'Template not found'
      });
    }

    if (template.line_id !== lineId) {
      return res.status(400).json({
        success: false,
        error: 'Template does not belong to the specified line'
      });
    }

    if (template.status !== 'approved') {
      return res.status(400).json({
        success: false,
        error: `Template is not approved (status: ${template.status})`
      });
    }

    // Get WhatsApp line
    const line = await WhatsAppLine.findByPk(lineId);

    if (!line || !line.is_active) {
      return res.status(404).json({
        success: false,
        error: 'WhatsApp line not found or inactive'
      });
    }

    // Normalize phone number
    const normalizedPhone = to.replace(/\D/g, '');
    if (!normalizedPhone.startsWith('57')) { // Adjust for your country
      return res.status(400).json({
        success: false,
        error: 'Invalid phone number format'
      });
    }

    // Get or create lead (filtered by company)
    // Use findOrCreate to handle race conditions and existing leads
    const [lead, created] = await Lead.findOrCreate({
      where: {
        phone_number: `+${normalizedPhone}`
      },
      defaults: {
        phone_number: `+${normalizedPhone}`,
        company_id: req.user.companyId,
        status: 'new',
        first_contact_date: new Date()
      }
    });

    // Verify the lead belongs to the requesting company
    if (lead.company_id !== req.user.companyId) {
      return res.status(403).json({
        success: false,
        error: 'Access denied',
        message: 'This phone number belongs to another company'
      });
    }

    // CRITICAL: Find existing ConversationAssignment to maintain campaign context
    // This ensures outgoing messages are associated with the same campaign as incoming messages
    const phoneVariations = getPhoneVariations(`+${normalizedPhone}`);
    const conversationAssignment = await ConversationAssignment.findOne({
      where: {
        phone_number: { [Op.in]: phoneVariations },
        line_id: lineId,
      },
      order: [['assigned_at', 'DESC']]  // Get the most recent assignment
    });

    // Extract campaign context from existing assignment
    let campaignId = null;
    let conversationAssignmentId = null;
    let assignedUserIds = null;

    if (conversationAssignment) {
      campaignId = conversationAssignment.campaign_id;
      conversationAssignmentId = conversationAssignment.id;
      assignedUserIds = conversationAssignment.assigned_user_id ? [conversationAssignment.assigned_user_id] : null;
      console.log('[sendTemplate] Found conversation assignment:', {
        campaign_id: campaignId,
        conversation_assignment_id: conversationAssignmentId,
        assigned_user_id: conversationAssignment.assigned_user_id
      });
    } else {
      console.log('[sendTemplate] No conversation assignment found for:', {
        phone_number: `+${normalizedPhone}`,
        line_id: lineId
      });
    }

    // Send template via Meta API
    const metaResponse = await TemplateManager.sendTemplateMessage({
      line,
      to: `+${normalizedPhone}`,
      template,
      variableValues,
      headerParams,
      buttonParams,
      headerCaption: headerCaption || null
    });

    // Build message content with variables replaced
    let messageContent = template.content;


    if (variableValues && variableValues.length > 0) {
      variableValues.forEach((value, index) => {
        const placeholder = `{{${index + 1}}}`;
        messageContent = messageContent.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value);
      });
    }

    // Prepare interactive data if template has buttons
    let interactiveType = null;
    let interactiveData = null;

    console.log('[sendTemplate] Template buttons:', JSON.stringify(template.buttons, null, 2));

    if (template.buttons && template.buttons.length > 0) {
      interactiveType = 'button';
      interactiveData = {
        body: messageContent,
        buttons: template.buttons
      };
      console.log('[sendTemplate] Setting interactive data:', JSON.stringify({ interactiveType, interactiveData }, null, 2));
    } else {
      console.log('[sendTemplate] No buttons found in template');
    }

    // Save message to database with campaign context
    const message = await MessageService.saveOutgoingMessage({
      line_id: line.id,
      lead_id: lead.id,
      company_id: req.user.companyId,
      user_id: req.user.id,
      template_id: template.id,
      phone_number: `+${normalizedPhone}`,
      message_content: messageContent,
      message_type: 'template',
      direction: 'outgoing',
      status: 'sent',
      meta_message_id: metaResponse.messages?.[0]?.id,
      is_mass_campaign: false,
      interactive_type: interactiveType,
      interactive_data: interactiveData,
      campaign_id: campaignId,
      conversation_assignment_id: conversationAssignmentId,
      assigned_user_id: assignedUserIds && assignedUserIds.length > 0 ? assignedUserIds[0] : null,
      assigned_user_ids: assignedUserIds
    });

    console.log('[sendTemplate] Message saved:', JSON.stringify({
      id: message.id,
      message_type: message.message_type,
      interactive_type: message.interactive_type,
      interactive_data: message.interactive_data
    }, null, 2));

    // Emit socket event for real-time update
    const io = req.app.get('io');
    if (io) {
      console.log('[sendTemplate] Emitting message:sent to line:', lineId);
      io.to(`line:${lineId}`).emit('message:sent', {
        message: message
      });
    }

    res.status(201).json({
      success: true,
      data: {
        message,
        metaMessageId: metaResponse.messages?.[0]?.id
      }
    });
  } catch (error) {
    console.error('Error sending template message:', error);
    next(error);
  }
}

