/**
 * Mass Campaign Service
 *
 * Handles mass message sending campaigns with bulk recipient processing
 * Integrates with MessageQueueService for rate-limited delivery
 *
 * Features:
 * - Campaign creation and management
 * - Bulk recipient processing
 * - Progress tracking
 * - Scheduled sending
 * - Campaign cancellation
 */

import { messageQueueService } from './MessageQueueService.js';
import Message from '../models/sequelize/Message.js';
import MessageTemplate from '../models/sequelize/MessageTemplate.js';
import PhoneLine from '../models/sequelize/PhoneLine.js';
import WhatsAppLine from '../models/sequelize/WhatsAppLine.js';
import Lead from '../models/sequelize/Lead.js';
import ConversationAssignment from '../models/sequelize/ConversationAssignment.js';
import PhoneLineUserAssignment from '../models/sequelize/PhoneLineUserAssignment.js';
import User from '../models/sequelize/User.js';
import SocketService from './SocketService.js';
import sequelize from '../config/sequelize.js';
import { AppError } from '../middleware/errorHandler.js';
import { Op } from 'sequelize';

/**
 * Mass Campaign Service Class
 */
class MassCampaignService {
  constructor() {
    // In-memory campaign tracking (use database in production)
    this.campaigns = new Map();
    this.campaignIdCounter = 1;
    this.initialized = false;
  }

  /**
   * Initialize service and recover pending scheduled campaigns
   * Call this when server starts
   */
  async initialize() {
    if (this.initialized) {
      console.log('[MassCampaignService] Already initialized');
      return;
    }

    console.log('[MassCampaignService] Initializing and recovering scheduled campaigns...');

    try {
      // Find all scheduled campaigns (placeholders that haven't been processed yet)
      const scheduledCampaigns = await Message.findAll({
        where: {
          phone_number: 'SCHEDULED_CAMPAIGN',
          is_mass_campaign: true,
          status: 'pending'
        }
      });

      console.log(`[MassCampaignService] Found ${scheduledCampaigns.length} scheduled campaign(s) to recover`);

      for (const placeholder of scheduledCampaigns) {
        const campaignId = placeholder.campaign_id;
        const scheduledAt = new Date(placeholder.scheduled_at);
        const now = new Date();

        console.log(`[MassCampaignService] Recovering campaign ${campaignId}, scheduled for ${scheduledAt.toISOString()}`);

        // Check if scheduled time has passed
        if (scheduledAt <= now) {
          // Execute immediately
          console.log(`[MassCampaignService] Campaign ${campaignId} is overdue, executing now`);
          this.processCampaign(campaignId);
        } else {
          // Re-schedule with setTimeout
          const delay = scheduledAt.getTime() - now.getTime();
          console.log(`[MassCampaignService] Re-scheduling campaign ${campaignId} to execute in ${(delay/60000).toFixed(2)} minutes`);

          setTimeout(() => {
            console.log(`[MassCampaign] Executing recovered campaign ${campaignId} NOW`);
            this.processCampaign(campaignId);
          }, delay);
        }
      }

      this.initialized = true;
      console.log('[MassCampaignService] Initialization complete');
    } catch (error) {
      console.error('[MassCampaignService] Error during initialization:', error);
    }
  }

  /**
   * Create a new mass campaign
   *
   * @param {Object} campaignData - Campaign configuration
   * @param {number} campaignData.lineId - WhatsApp line ID
   * @param {number} campaignData.templateId - Message template ID
   * @param {Array<Object>} campaignData.recipients - List of recipients [{phone, name, variables}]
   * @param {Object} campaignData.templateVariables - Template variables
   * @param {Object} campaignData.headerParams - Header parameters (text or media)
   * @param {Array} campaignData.buttonParams - Button parameters for dynamic buttons
   * @param {Date} campaignData.scheduledAt - Scheduled send time (optional)
   * @param {number} campaignData.userId - User creating the campaign
   * @param {Array<number>} campaignData.assignedUserIds - Array of agent or admin IDs to assign campaign responses to (optional)
   * @param {boolean} campaignData.assignToSelf - If true, assign to the user creating the campaign
   * @returns {Promise<Object>} Campaign object
   */
  async createCampaign(campaignData) {
    const {
      campaignName,
      lineId,
      templateId,
      recipients,
      templateVariables,
      headerParams,
      headerCaption,
      buttonParams,
      scheduledAt,
      userId,
      assignedUserIds,
      assignToSelf
    } = campaignData;
      console.log('[MessageService] Saving outgoing message for user_id:', campaignData);

    // Validate inputs
    if (!lineId || !templateId || !recipients || recipients.length === 0) {
      throw new AppError('Missing required campaign data', 400);
    }

    // Verify line exists and is active
    const line = await PhoneLine.findByPk(lineId);
    if (!line || !line.is_active) {
      throw new AppError('WhatsApp line not found or inactive', 404);
    }

    // Find corresponding WhatsAppLine for message creation (Message model uses line_id)
    const whatsappLine = await WhatsAppLine.findOne({
      where: { phone_number: line.phone_number, is_active: true }
    });

    if (!whatsappLine) {
      throw new AppError('Corresponding WhatsApp line not found for message sending', 404);
    }

    // Verify template exists and is approved
    const template = await MessageTemplate.findByPk(templateId);
    if (!template) {
      throw new AppError('Message template not found', 404);
    }

    if (template.status !== 'approved') {
      throw new AppError('Template must be approved before use', 400);
    }

    // Determine assigned user IDs (supports multiple agents/admins)
    let finalAssignedUserIds = [];
    if (assignToSelf) {
      finalAssignedUserIds = [userId];
    } else if (assignedUserIds && Array.isArray(assignedUserIds) && assignedUserIds.length > 0) {
      finalAssignedUserIds = assignedUserIds;
    }

    // If there are assigned users, validate they all have access to the line
    if (finalAssignedUserIds.length > 0) {
      for (const assignedUserId of finalAssignedUserIds) {
        const assignedUser = await User.findByPk(assignedUserId, {
          include: ['role']
        });

        if (!assignedUser || !assignedUser.is_active) {
          throw new AppError(`Assigned user ${assignedUserId} not found or inactive`, 400);
        }

        if (assignedUser.role.role_name !== 'agent' && assignedUser.role.role_name !== 'admin') {
          throw new AppError(`User ${assignedUserId} must be an agent or admin`, 400);
        }

        // Verify user has access to this line
        const lineAssignment = await PhoneLineUserAssignment.findOne({
          where: {
            user_id: assignedUserId,
            phone_line_id: lineId,
          },
        });

        if (!lineAssignment) {
          throw new AppError(`User ${assignedUserId} does not have access to this line`, 400);
        }
      }
    }

    // Validate recipients phone numbers and remove duplicates
    const validRecipients = [];
    const invalidRecipients = [];
    const seenPhones = new Set();
    let duplicatesCount = 0;

    for (const recipient of recipients) {
      if (this.isValidPhoneNumber(recipient.phone)) {
        const normalizedPhone = this.normalizePhoneNumber(recipient.phone);

        // Check for duplicates
        if (!seenPhones.has(normalizedPhone)) {
          seenPhones.add(normalizedPhone);
          validRecipients.push({
            phone: normalizedPhone,
            name: recipient.name || null,
            variables: recipient.variables || {}
          });
        } else {
          duplicatesCount++;
        }
      } else {
        invalidRecipients.push(recipient.phone);
      }
    }

    if (validRecipients.length === 0) {
      throw new AppError('No valid recipients found', 400);
    }

    // Log warning if duplicates were found
    if (duplicatesCount > 0) {
      console.log(`[MassCampaignService] Removed ${duplicatesCount} duplicate recipient(s) for campaign`);
    }

    // Create campaign object
    const campaignId = `campaign_${Date.now()}_${this.campaignIdCounter++}`;
    const campaign = {
      id: campaignId,
      name: campaignName,
      lineId,
      whatsappLineId: whatsappLine.id,
      templateId,
      templateName: template.name,
      userId,
      assignedUserIds: finalAssignedUserIds, // Array of assigned agent/admin IDs
      recipients: validRecipients,
      invalidRecipients,
      templateVariables: templateVariables || {},
      headerParams: headerParams || {},
      headerCaption: headerCaption || null,
      buttonParams: buttonParams || [],
      scheduledAt: scheduledAt || null,
      status: scheduledAt ? 'scheduled' : 'processing',
      totalRecipients: validRecipients.length,
      sentCount: 0,
      failedCount: 0,
      pendingCount: validRecipients.length,
      createdAt: new Date(),
      startedAt: null,
      completedAt: null,
      messages: [] // Track message IDs
    };

    // Store campaign in memory
    this.campaigns.set(campaignId, campaign);

    // Debug: Verify campaign was stored correctly
    const storedCampaign = this.campaigns.get(campaignId);
    console.log(`[MassCampaign] Campaign stored in memory:`, {
      id: storedCampaign?.id,
      templateId: storedCampaign?.templateId,
      totalRecipients: storedCampaign?.totalRecipients,
      hasRecipients: !!storedCampaign?.recipients,
      recipientsCount: storedCampaign?.recipients?.length
    });

    // If not scheduled, start sending immediately
    if (!scheduledAt) {
      this.processCampaign(campaignId);
    } else {
      // Schedule campaign processing
      // Parse scheduledAt to UTC timestamp to ensure proper timezone handling
      const scheduledTime = new Date(scheduledAt).getTime();
      const now = Date.now();
      const delay = scheduledTime - now;

      // Log for debugging timezone issues
      console.log(`[MassCampaign] Scheduling validation:`);
      console.log(`  - Scheduled time (input): ${scheduledAt}`);
      console.log(`  - Scheduled time (parsed): ${new Date(scheduledTime).toISOString()}`);
      console.log(`  - Current time (server): ${new Date(now).toISOString()}`);
      console.log(`  - Delay in minutes: ${(delay / 60000).toFixed(2)}`);

      // Allow a small tolerance (1 minute) for timezone/clock differences
      if (delay > -60000) {
        // Create a placeholder message to show the scheduled campaign immediately
        await this.createScheduledCampaignPlaceholder(campaign);

        // Schedule the actual sending
        const effectiveDelay = Math.max(0, delay);
        console.log(`[MassCampaign] Scheduling campaign ${campaignId} to execute in ${effectiveDelay}ms (${(effectiveDelay/60000).toFixed(2)} minutes)`);

        setTimeout(() => {
          console.log(`[MassCampaign] Executing scheduled campaign ${campaignId} NOW`);
          this.processCampaign(campaignId);
        }, effectiveDelay);

        console.log(`[MassCampaign] Campaign ${campaignId} scheduled successfully`);
      } else {
        throw new AppError('Scheduled time must be in the future', 400);
      }
    }

    return {
      campaignId: campaign.id,
      status: campaign.status,
      totalRecipients: campaign.totalRecipients,
      invalidRecipients: campaign.invalidRecipients,
      duplicatesRemoved: duplicatesCount,
      scheduledAt: campaign.scheduledAt,
      createdAt: campaign.createdAt
    };
  }

  /**
   * Create a placeholder message to show scheduled campaign immediately
   * Also stores campaign data in interactive_data for recovery after server restart
   *
   * @param {Object} campaign - Campaign object
   */
  async createScheduledCampaignPlaceholder(campaign) {
    try {
      // Store essential campaign data for recovery
      const campaignData = {
        id: campaign.id,
        name: campaign.name,
        lineId: campaign.lineId,
        whatsappLineId: campaign.whatsappLineId,
        templateId: campaign.templateId,
        userId: campaign.userId,
        assignedUserIds: campaign.assignedUserIds,
        recipients: campaign.recipients,
        templateVariables: campaign.templateVariables,
        headerParams: campaign.headerParams,
        headerCaption: campaign.headerCaption,
        buttonParams: campaign.buttonParams,
        scheduledAt: campaign.scheduledAt,
        totalRecipients: campaign.totalRecipients
      };

      // Create a single placeholder message to represent the scheduled campaign
      await Message.create({
        line_id: campaign.whatsappLineId,
        lead_id: null, // No specific lead for placeholder
        user_id: campaign.userId,
        template_id: campaign.templateId,
        phone_number: 'SCHEDULED_CAMPAIGN', // Special marker
        message_content: `Campaña programada: ${campaign.name} - ${campaign.totalRecipients} destinatarios`,
        message_type: 'template',
        direction: 'outgoing',
        status: 'pending', // Use 'pending' status to indicate it's scheduled
        is_mass_campaign: true,
        campaign_id: campaign.id,
        campaign_name: campaign.name,
        scheduled_at: campaign.scheduledAt, // Save the scheduled time
        assigned_user_id: campaign.assignedUserIds && campaign.assignedUserIds.length > 0 ? campaign.assignedUserIds[0] : null,
        assigned_user_ids: campaign.assignedUserIds && campaign.assignedUserIds.length > 0 ? campaign.assignedUserIds : null,
        interactive_data: campaignData // Store campaign data for recovery
      });

      console.log(`[MassCampaign] Created placeholder for scheduled campaign ${campaign.id} at ${campaign.scheduledAt}`);
    } catch (error) {
      console.error(`[MassCampaign] Error creating placeholder for campaign ${campaign.id}:`, error);
      // Don't throw - this is just for visibility, shouldn't block the scheduling
    }
  }

  /**
   * Recover campaign data from database (e.g., after server restart)
   *
   * @param {string} campaignId - Campaign ID
   * @returns {Promise<Object|null>} Recovered campaign object or null
   */
  async recoverCampaignFromDatabase(campaignId) {
    try {
      // Find the placeholder message that contains campaign data
      const placeholder = await Message.findOne({
        where: {
          campaign_id: campaignId,
          phone_number: 'SCHEDULED_CAMPAIGN',
          is_mass_campaign: true
        }
      });

      if (!placeholder || !placeholder.interactive_data) {
        console.error(`[MassCampaign] No placeholder found for campaign ${campaignId}`);
        return null;
      }

      // Reconstruct campaign object from stored data
      const campaignData = placeholder.interactive_data;
      const campaign = {
        id: campaignData.id,
        name: campaignData.name,
        lineId: campaignData.lineId,
        whatsappLineId: campaignData.whatsappLineId,
        templateId: campaignData.templateId,
        userId: campaignData.userId,
        assignedUserIds: campaignData.assignedUserIds,
        recipients: campaignData.recipients,
        templateVariables: campaignData.templateVariables,
        headerParams: campaignData.headerParams,
        headerCaption: campaignData.headerCaption,
        buttonParams: campaignData.buttonParams,
        scheduledAt: campaignData.scheduledAt,
        totalRecipients: campaignData.totalRecipients,
        status: 'scheduled',
        sentCount: 0,
        failedCount: 0,
        pendingCount: campaignData.totalRecipients,
        createdAt: placeholder.created_at,
        startedAt: null,
        completedAt: null,
        messages: []
      };

      console.log(`[MassCampaign] Successfully recovered campaign ${campaignId} from database`);
      return campaign;
    } catch (error) {
      console.error(`[MassCampaign] Error recovering campaign ${campaignId} from database:`, error);
      return null;
    }
  }

  /**
   * Process campaign - send messages to all recipients
   *
   * @param {number} campaignId - Campaign ID
   */
  async processCampaign(campaignId) {
    console.log(`[MassCampaign] processCampaign called for: ${campaignId}`);

    // Try to get campaign from memory first
    let campaign = this.campaigns.get(campaignId);

    console.log(`[MassCampaign] Campaign from memory:`, {
      found: !!campaign,
      id: campaign?.id,
      templateId: campaign?.templateId,
      hasRecipients: !!campaign?.recipients,
      recipientsCount: campaign?.recipients?.length
    });

    // If not in memory OR if templateId is undefined (corrupted), recover from database
    if (!campaign || !campaign.templateId || !campaign.recipients) {
      console.log(`[MassCampaign] Campaign ${campaignId} not in memory or corrupted, attempting to recover from database`);
      campaign = await this.recoverCampaignFromDatabase(campaignId);

      if (!campaign) {
        console.error(`[MassCampaign] Campaign ${campaignId} not found in memory or database`);
        return;
      }

      console.log(`[MassCampaign] Campaign recovered from database:`, {
        id: campaign.id,
        templateId: campaign.templateId,
        recipientsCount: campaign.recipients?.length,
        templateVariables: campaign.templateVariables,
        headerParams: campaign.headerParams,
        buttonParams: campaign.buttonParams
      });

      // Store recovered campaign in memory
      this.campaigns.set(campaignId, campaign);
    }

    campaign.status = 'sending';
    campaign.startedAt = new Date();

    // Delete the placeholder message for scheduled campaigns
    if (campaign.scheduledAt) {
      try {
        await Message.destroy({
          where: {
            campaign_id: campaignId,
            phone_number: 'SCHEDULED_CAMPAIGN'
          }
        });
        console.log(`[MassCampaign] Removed placeholder for campaign ${campaignId}`);
      } catch (error) {
        console.error(`[MassCampaign] Error removing placeholder for campaign ${campaignId}:`, error);
      }
    }

    // Get template details
    const template = await MessageTemplate.findByPk(campaign.templateId);
    if (!template) {
      campaign.status = 'failed';
      campaign.completedAt = new Date();
      console.error(`[MassCampaign] Template ${campaign.templateId} not found for campaign ${campaignId}`);
      return;
    }

    // Process each recipient
    const sendPromises = campaign.recipients.map((recipient) =>
      this.sendCampaignMessage(campaign, recipient, template)
    );

    // Wait for all messages to be queued
    await Promise.allSettled(sendPromises);

    // Campaign will update to completed when all messages are processed
    this.checkCampaignCompletion(campaignId);
  }

  /**
   * Send message to single campaign recipient
   *
   * @param {Object} campaign - Campaign object
   * @param {Object} recipient - Recipient object
   * @param {Object} template - Template object
   */
  async sendCampaignMessage(campaign, recipient, template) {
    try {
      // Get line to obtain company_id
      const line = await WhatsAppLine.findByPk(campaign.lineId);
      if (!line) {
        throw new Error('WhatsApp line not found');
      }

      // Create or find lead for this company
      // Use findOrCreate to handle race conditions and existing leads
      // With composite unique index (phone_number, company_id), each company can have their own lead for the same number
      const [lead, created] = await Lead.findOrCreate({
        where: {
          phone_number: recipient.phone,
          company_id: line.company_id
        },
        defaults: {
          phone_number: recipient.phone,
          company_id: line.company_id,
          name: recipient.name,
          status: 'new',
          first_contact_date: new Date()
        }
      });

      // Prepare template variables
      const variables = {
        ...campaign.templateVariables,
        ...recipient.variables
      };

      // Debug: Log variables being used
      console.log(`\n🔍 [MASS CAMPAIGN DEBUG] Variables for ${recipient.phone}:`);
      console.log(`  - campaign.templateVariables:`, JSON.stringify(campaign.templateVariables, null, 2));
      console.log(`  - recipient.variables:`, JSON.stringify(recipient.variables, null, 2));
      console.log(`  - merged variables:`, JSON.stringify(variables, null, 2));

      // Parse template variables to get the order
      const templateVars = typeof template.variables === 'string'
        ? JSON.parse(template.variables)
        : template.variables || [];

      // Build message content with variables replaced by index
      let messageContent = template.content;
      templateVars.forEach((varDef, index) => {
        const placeholder = `{{${index + 1}}}`;
        const value = variables[varDef.name] || '';
        messageContent = messageContent.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value);
      });

      // Prepare interactive data if template has buttons
      let interactiveType = null;
      let interactiveData = null;

      if (template.buttons && template.buttons.length > 0) {
        interactiveType = 'button';
        interactiveData = {
          body: messageContent,
          buttons: template.buttons
        };
      }

      // Get or create conversation assignment for this user and phone number
      // Each user gets their own independent conversation with the same number
      // Use assigned user if specified, otherwise use the campaign creator

      console.log(campaign)
      const assignedUserId = (campaign.assignedUserIds && campaign.assignedUserIds.length > 0)
        ? campaign.assignedUserIds[0]
        : campaign.userId;

      const [conversationAssignment, created] = await ConversationAssignment.findOrCreate({
        where: {
          phone_number: recipient.phone,
          line_id: campaign.whatsappLineId,
          assigned_user_id: assignedUserId
        },
        defaults: {
          assigned_at: new Date(),
          assigned_by_user_id: campaign.userId,
          campaign_id: campaign.id
        }
      });

      // CRITICAL: Update assigned_at AND campaign_id every time this user sends a campaign message
      // This ensures replies go to the LAST user who contacted this number AND the LATEST campaign
      if (!created) {
        await conversationAssignment.update({
          assigned_at: new Date(),
          campaign_id: campaign.id  // Update to latest campaign
        });
      }

      // Create message record with pending status
      const message = await Message.create({
        line_id: campaign.whatsappLineId,
        lead_id: lead.id,
        company_id: line.company_id,
        user_id: campaign.userId,
        template_id: campaign.templateId,
        phone_number: recipient.phone,
        message_content: messageContent,
        message_type: 'template',
        direction: 'outgoing',
        status: 'pending',
        is_mass_campaign: true,
        campaign_id: campaign.id,
        campaign_name: campaign.name,
        assigned_user_id: campaign.assignedUserIds && campaign.assignedUserIds.length > 0 ? campaign.assignedUserIds[0] : null, // Keep first for backward compatibility
        assigned_user_ids: campaign.assignedUserIds && campaign.assignedUserIds.length > 0 ? campaign.assignedUserIds : null, // Array of assigned agents/admins
        conversation_assignment_id: conversationAssignment.id, // Link message to specific conversation
        interactive_type: interactiveType,
        interactive_data: interactiveData
      });

      campaign.messages.push(message.id);

      // Enqueue message for sending
      console.log(`\n📤 [MASS CAMPAIGN] Preparing to send message to ${recipient.phone}`);
      console.log(`📤 [MASS CAMPAIGN] Campaign headerParams:`, JSON.stringify(campaign.headerParams, null, 2));
      console.log(`📤 [MASS CAMPAIGN] Campaign headerCaption:`, campaign.headerCaption);
      console.log(`📤 [MASS CAMPAIGN] Campaign buttonParams:`, JSON.stringify(campaign.buttonParams, null, 2));

      const templateComponents = this.buildTemplateComponents(
        template,
        variables,
        campaign.headerParams,
        campaign.buttonParams,
        campaign.headerCaption
      );

      await messageQueueService.enqueue({
        lineId: campaign.whatsappLineId,
        to: recipient.phone,
        type: 'template',
        content: {
          templateName: template.name,
          languageCode: template.language || 'es',
          components: templateComponents
        },
        priority: 3, // Lower priority for mass campaigns
        onSuccess: async (result) => {
          // Update message with Meta message ID
          await Message.update(
            {
              status: 'sent',
              meta_message_id: result.messages?.[0]?.id
            },
            { where: { id: message.id } }
          );

          // Get updated message to emit via socket
          const updatedMessage = await Message.findByPk(message.id);

          // Emit to all assigned users if they exist
          if (campaign.assignedUserIds && campaign.assignedUserIds.length > 0) {
            await SocketService.emitIncomingMessage(campaign.whatsappLineId, updatedMessage.toJSON());
          }

          // Update campaign stats
          campaign.sentCount++;
          campaign.pendingCount--;
          this.checkCampaignCompletion(campaign.id);
        },
        onError: async (error) => {
          // Update message status to failed
          await Message.update(
            { status: 'failed' },
            { where: { id: message.id } }
          );

          // Update campaign stats
          campaign.failedCount++;
          campaign.pendingCount--;
          this.checkCampaignCompletion(campaign.id);

          console.error(`Failed to send message to ${recipient.phone}:`, error.message);
        }
      });

    } catch (error) {
      campaign.failedCount++;
      campaign.pendingCount--;
      console.error(`Error processing recipient ${recipient.phone}:`, error.message);
    }
  }

  /**
   * Check if campaign is completed and update status
   *
   * @param {number} campaignId - Campaign ID
   */
  checkCampaignCompletion(campaignId) {
    const campaign = this.campaigns.get(campaignId);
    if (!campaign) {
      return;
    }

    if (campaign.pendingCount === 0 && campaign.status === 'sending') {
      campaign.status = 'completed';
      campaign.completedAt = new Date();
    }
  }

  /**
   * Get campaign by ID
   *
   * @param {string} campaignId - Campaign ID
   * @returns {Promise<Object|null>} Campaign object
   */
  async getCampaign(campaignId) {
    try {
      const campaignData = await Message.findOne({
        where: {
          campaign_id: campaignId,
          is_mass_campaign: true
        },
        include: [
          {
            model: MessageTemplate,
            as: 'template',
            attributes: ['name']
          }
        ],
        attributes: [
          'campaign_id',
          'campaign_name',
          'line_id',
          'template_id',
          'user_id',
          'assigned_user_id',
          'scheduled_at',
          [sequelize.fn('MIN', sequelize.col('Message.created_at')), 'createdAt']
        ],
        group: ['campaign_id', 'campaign_name', 'line_id', 'template_id', 'user_id', 'assigned_user_id', 'scheduled_at', 'template.id', 'template.name'],
        raw: true
      });

      if (!campaignData) {
        return null;
      }

      // Get statistics for this campaign
      const stats = await Message.findOne({
        where: {
          campaign_id: campaignId,
          is_mass_campaign: true
        },
        attributes: [
          [sequelize.fn('COUNT', sequelize.col('id')), 'totalRecipients'],
          [sequelize.fn('SUM', sequelize.literal("CASE WHEN status = 'sent' THEN 1 ELSE 0 END")), 'sentCount'],
          [sequelize.fn('SUM', sequelize.literal("CASE WHEN status = 'failed' THEN 1 ELSE 0 END")), 'failedCount'],
          [sequelize.fn('SUM', sequelize.literal("CASE WHEN status = 'pending' THEN 1 ELSE 0 END")), 'pendingCount']
        ],
        raw: true
      });

      const totalRecipients = parseInt(stats.totalRecipients) || 0;
      const sentCount = parseInt(stats.sentCount) || 0;
      const failedCount = parseInt(stats.failedCount) || 0;
      const pendingCount = parseInt(stats.pendingCount) || 0;

      return {
        id: campaignData.campaign_id,
        name: campaignData.campaign_name,
        lineId: campaignData.line_id,
        templateId: campaignData.template_id,
        templateName: campaignData['template.name'],
        userId: campaignData.user_id,
        assignedUserId: campaignData.assigned_user_id,
        scheduledAt: campaignData.scheduled_at,
        status: pendingCount > 0 ? 'pending' : (sentCount > 0 ? 'sent' : 'failed'),
        totalRecipients,
        sentCount,
        failedCount,
        pendingCount,
        createdAt: campaignData.createdAt,
        progress: totalRecipients > 0
          ? ((sentCount + failedCount) / totalRecipients * 100).toFixed(2)
          : 0
      };
    } catch (error) {
      console.error('Error fetching campaign:', error);
      throw new Error('Could not retrieve campaign');
    }
  }

  /**
   * Get all campaigns
   *
   * @param {Object} filters - Filter options
   * @param {number} filters.lineId - Filter by line ID
   * @param {string} filters.status - Filter by status
   * @param {number} filters.userId - Filter by user ID
   * @param {number} filters.companyId - Filter by company ID
   * @returns {Array<Object>} Array of campaigns
   */
  async getAllCampaigns(filters = {}) {

    const where = {
      is_mass_campaign: true,
      campaign_id: { [Op.ne]: null }
    };

    if (filters.lineId) {
      where.line_id = filters.lineId;
    }
    if (filters.userId) {
      where.user_id = filters.userId;
    }
    if (filters.companyId !== undefined) {
      where.company_id = filters.companyId;
    }

    try {
      const campaignsSummary = await Message.findAll({
        where: where,
        include: [
          {
          model: MessageTemplate,
          as: 'template',
          attributes: ['name'] 
          },

      ],

        group: [
          'Message.campaign_id',
          'Message.campaign_name',
          'Message.line_id',
          'Message.template_id',
          'template.id',
          'template.name'
        ],

        attributes: [
          'campaign_id',
          'campaign_name',
          'line_id',
          'status',
          'template_id',
          [sequelize.col('template.name'), 'templateName'],
          [sequelize.literal('(SELECT assigned_user_ids FROM messages WHERE campaign_id = Message.campaign_id LIMIT 1)'), 'assigned_user_ids'],
          [sequelize.literal('(SELECT scheduled_at FROM messages WHERE campaign_id = Message.campaign_id LIMIT 1)'), 'scheduled_at'],
          [sequelize.fn('COUNT', sequelize.col('Message.id')), 'totalRecipients'],
          [
            sequelize.fn('SUM', sequelize.literal("CASE WHEN Message.status = 'sent' THEN 1 ELSE 0 END")),
            'sentCount'
          ],
          [
            sequelize.fn('SUM', sequelize.literal("CASE WHEN Message.status = 'failed' THEN 1 ELSE 0 END")),
            'failedCount'
          ],
          [
            sequelize.fn('SUM', sequelize.literal("CASE WHEN Message.status = 'pending' THEN 1 ELSE 0 END")),
            'pendingCount'
          ],
          [sequelize.fn('MIN', sequelize.col('Message.created_at')), 'createdAt'],
          [sequelize.fn('MAX', sequelize.col('Message.updated_at')), 'completedAt']
        ],

        order: [['createdAt', 'DESC']],
        raw: true 
      });



      for (const campaign of campaignsSummary) {
        this.campaigns.set(campaign.campaign_id, campaign);
      }

      return campaignsSummary.map(campaign => ({
        id: campaign.campaign_id,
        name: campaign.campaign_name,
        lineId: campaign.line_id,
        templateId: campaign.template_id,
        templateName: campaign.templateName,
        status: campaign.status,
        scheduledAt: campaign.scheduled_at,
        assignedUserIds: campaign.assigned_user_ids ?
          (typeof campaign.assigned_user_ids === 'string' ? JSON.parse(campaign.assigned_user_ids) : campaign.assigned_user_ids)
          : null, // JSON array of assigned agent/admin IDs

        totalRecipients: parseInt(campaign.totalRecipients),
        sentCount: parseInt(campaign.sentCount),
        failedCount: parseInt(campaign.failedCount),
        pendingCount: parseInt(campaign.pendingCount),

        createdAt: campaign.createdAt,
        completedAt: campaign.completedAt
      }));

    } catch (error) {
      console.error('Error fetching campaign summary:', error);
      // Lanza tu AppError
      throw new Error('Could not retrieve campaign summary'); 
    }
  }

  /**
   * Cancel campaign
   *
   * @param {string} campaignId - Campaign ID
   * @returns {Promise<boolean>} True if cancelled
   */
  async cancelCampaign(campaignId) {
    const campaign = await this.getCampaign(campaignId);
    if (!campaign) {
      throw new AppError('Campaign not found', 404);
    }

    if (campaign.status === 'sent' || campaign.status === 'cancelled') {
      throw new AppError('Cannot cancel completed or already cancelled campaign', 400);
    }

    // Update all pending messages from this campaign to 'cancelled'
    await Message.update(
      { status: 'cancelled' },
      {
        where: {
          campaign_id: campaignId,
          status: 'pending'
        }
      }
    );

    return true;
  }

  /**
   * Validate phone number format (E.164)
   *
   * @param {string} phone - Phone number
   * @returns {boolean} True if valid
   */
  isValidPhoneNumber(phone) {
    if (!phone.startsWith('+')) {
      phone = '+' + phone;
    }
    const e164Regex = /^\+[1-9]\d{1,14}$/;
    return e164Regex.test(phone);
  }

  /**
   * Normalize phone number to E.164 format
   *
   * @param {string} phone - Phone number
   * @returns {string} Normalized phone number
   */
  normalizePhoneNumber(phone) {
    // Remove all non-digit characters except leading +
    let normalized = phone.replace(/[^\d+]/g, '');

    // Ensure it starts with +
    if (!normalized.startsWith('+')) {
      normalized = '+' + normalized;
    }

    return normalized;
  }

  /**
   * Fill template variables in content
   *
   * @param {string} content - Template content
   * @param {Object} variables - Variables object
   * @returns {string} Content with variables replaced
   */
  fillTemplateVariables(content, variables) {
    let filled = content;

    Object.keys(variables).forEach(key => {
      const placeholder = `{{${key}}}`;
      filled = filled.replace(new RegExp(placeholder, 'g'), variables[key]);
    });

    return filled;
  }

  /**
   * Build template components for WhatsApp API
   *
   * @param {Object} template - Template object
   * @param {Object} variables - Variables object for body
   * @param {Object} headerParams - Header parameters
   * @param {Array} buttonParams - Button parameters
   * @returns {Array<Object>} Template components
   */
  buildTemplateComponents(template, variables, headerParams = {}, buttonParams = [], headerCaption = null) {
    console.log(`\n========== BUILD TEMPLATE COMPONENTS ==========`);
    console.log(`Template: ${template.name} (ID: ${template.id})`);
    console.log(`Header Type: ${template.header_type}`);
    console.log(`Variables:`, JSON.stringify(variables, null, 2));
    console.log(`headerParams:`, JSON.stringify(headerParams, null, 2));
    console.log(`buttonParams:`, JSON.stringify(buttonParams, null, 2));
    console.log(`headerCaption:`, headerCaption);
    console.log(`===============================================\n`);

    const components = [];

    // 1. HEADER parameters (if header has variables or media)
    if (template.header_type && template.header_type !== 'NONE') {
      console.log(`🔍 [MASS CAMPAIGN] Template has header type: ${template.header_type}`);
      if (template.header_type === 'TEXT' && headerParams.text) {
        // Header with text variables
        components.push({
          type: 'header',
          parameters: [{
            type: 'text',
            text: headerParams.text
          }]
        });
      } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(template.header_type)) {
        // Media header
        const mediaType = template.header_type.toLowerCase();
        console.log(`🔍 [MASS CAMPAIGN] Processing ${mediaType} header for template "${template.name}"`);
        console.log(`🔍 [MASS CAMPAIGN] headerParams received:`, JSON.stringify(headerParams, null, 2));
        console.log(`🔍 [MASS CAMPAIGN] template.header_content:`, template.header_content);
        console.log(`🔍 [MASS CAMPAIGN] headerCaption:`, headerCaption);
        console.log(`🔍 [MASS CAMPAIGN] template.header_caption:`, template.header_caption);

        // If headerParams provided, use that. Otherwise, use header_content (public URL)
        let mediaParam = headerParams[mediaType];
        console.log(`🔍 [MASS CAMPAIGN] mediaParam from headerParams[${mediaType}]:`, mediaParam);

        if (!mediaParam && template.header_content) {
          console.log(`🔍 [MASS CAMPAIGN] No mediaParam provided, checking template.header_content`);
          // Check if header_content is a valid URL (not a handle like h:xxxxx)
          if (template.header_content.startsWith('http://') || template.header_content.startsWith('https://')) {
            // Use the public URL saved in header_content
            mediaParam = { link: template.header_content };
            console.log(`✅ [MASS CAMPAIGN] Using template default URL:`, mediaParam);
          } else if (template.header_content.startsWith('h:')) {
            // This is a handle, not a URL - cannot be used for sending messages
            console.error(`❌ [MASS CAMPAIGN] Template has media handle but no public URL`);
            throw new Error(`Template "${template.name}" has a media handle but no public URL. Please re-upload the media file.`);
          } else {
            console.warn(`⚠️  [MASS CAMPAIGN] template.header_content exists but is not a valid URL or handle:`, template.header_content);
          }
        }

        if (mediaParam) {
          // Handle caption/filename based on media type
          const caption = headerCaption || template.header_caption;

          if (mediaType === 'document') {
            // For DOCUMENTS: filename is the name shown when downloading the file
            // Set filename (priority: 1. from upload, 2. headerCaption, 3. template.header_caption)
            if (!mediaParam.filename && caption) {
              mediaParam = {
                ...mediaParam,
                filename: caption
              };
            }
            // Keep filename if it already exists (from upload)
          } else if (mediaType === 'image' || mediaType === 'video') {
            // For images/videos: only caption field
            if (caption) {
              mediaParam = {
                ...mediaParam,
                caption: caption
              };
            }
          }

          const headerComponent = {
            type: 'header',
            parameters: [{
              type: mediaType,
              [mediaType]: mediaParam
            }]
          };
          console.log(`✅ [MASS CAMPAIGN] Header component built:`, JSON.stringify(headerComponent, null, 2));
          components.push(headerComponent);
        } else {
          console.error(`❌ [MASS CAMPAIGN] No mediaParam available for ${mediaType} header!`);
          console.error(`❌ [MASS CAMPAIGN] Template "${template.name}" requires ${mediaType} but none provided`);
        }
      }
    }

    // 2. BODY parameters
    const templateVars = template.variables || [];
    if (templateVars.length > 0) {
      const parsedTemplateVars = typeof templateVars === 'string'
        ? JSON.parse(templateVars)
        : templateVars;

      const parameters = parsedTemplateVars.map(varDef => {
        const value = variables[varDef.name] || '';
        return {
          type: 'text',
          text: String(value)
        };
      });

      components.push({
        type: 'body',
        parameters
      });
    }

    // 3. BUTTON parameters (for URL buttons with variables or COPY_CODE)
    if (buttonParams && buttonParams.length > 0) {
      buttonParams.forEach((param) => {
        if (param.type === 'url' && param.text) {
          // URL button with dynamic suffix
          components.push({
            type: 'button',
            sub_type: 'url',
            index: param.index,
            parameters: [{
              type: 'text',
              text: param.text
            }]
          });
        } else if (param.type === 'copy_code' && param.code) {
          // Copy code button
          components.push({
            type: 'button',
            sub_type: 'copy_code',
            index: param.index,
            parameters: [{
              type: 'coupon_code',
              coupon_code: param.code
            }]
          });
        }
      });
    }

    console.log(`\n========== FINAL COMPONENTS ==========`);
    console.log(`Total components: ${components.length}`);
    console.log(JSON.stringify(components, null, 2));
    console.log(`======================================\n`);

    return components;
  }

  /**
   * Get campaign statistics
   *
   * @param {string} campaignId - Campaign ID
   * @returns {Promise<Object>} Campaign statistics
   */
  async getCampaignStats(campaignId) {
    // Get campaign data from database
    const campaign = await this.getCampaign(campaignId);
    if (!campaign) {
      throw new AppError('Campaign not found', 404);
    }

    const messageStats = await Message.findAll({
      where: {
        campaign_id: campaignId,
        is_mass_campaign: true
      },
      attributes: [
        'status',
        [sequelize.fn('COUNT', sequelize.col('id')), 'count']
      ],
      group: ['status'],
      raw: true
    });

    const stats = {
      campaignId: campaign.id,
      status: campaign.status,
      totalRecipients: campaign.totalRecipients,
      sentCount: campaign.sentCount,
      failedCount: campaign.failedCount,
      pendingCount: campaign.pendingCount,
      messageStatusBreakdown: messageStats.map(stat => ({
        status: stat.status,
        count: parseInt(stat.count)
      })),
      createdAt: campaign.createdAt
    };

    return stats;
  }

  /**
   * Assign or reassign agents/admins to all leads in a campaign
   *
   * @param {string} campaignId - Campaign ID
   * @param {Array<number>|null} assignedUserIds - Array of agent or admin user IDs to assign (null/empty to unassign)
   * @param {number} assignedByUserId - User performing the assignment
   * @returns {Promise<Object>} Assignment result
   */
  async assignAgentToCampaign(campaignId, assignedUserIds, assignedByUserId) {
    // Get campaign from database
    const campaign = await this.getCampaign(campaignId);
    if (!campaign) {
      throw new AppError('Campaign not found', 404);
    }

    // Normalize input to array
    const userIdsArray = Array.isArray(assignedUserIds) ? assignedUserIds : (assignedUserIds ? [assignedUserIds] : []);

    // If assigning to users, validate they all have access to the line
    if (userIdsArray.length > 0) {
      for (const userId of userIdsArray) {
        const assignedUser = await User.findByPk(userId, {
          include: ['role']
        });

        if (!assignedUser || !assignedUser.is_active) {
          throw new AppError(`Assigned user ${userId} not found or inactive`, 400);
        }

        if (assignedUser.role.role_name !== 'agent' && assignedUser.role.role_name !== 'admin') {
          throw new AppError(`User ${userId} must be an agent or admin`, 400);
        }

        // Verify user has access to this line
        const lineAssignment = await PhoneLineUserAssignment.findOne({
          where: {
            user_id: userId,
            line_id: campaign.whatsappLineId,
          },
        });

        if (!lineAssignment) {
          throw new AppError(`User ${userId} does not have access to this line`, 400);
        }
      }
    }

    // Update all messages from this campaign with new assigned_user_ids
    const updateResult = await Message.update(
      {
        assigned_user_ids: userIdsArray.length > 0 ? userIdsArray : null,
        assigned_user_id: userIdsArray.length > 0 ? userIdsArray[0] : null // Keep first for backward compatibility
      },
      {
        where: {
          campaign_id: campaignId,
          is_mass_campaign: true
        }
      }
    );

    return {
      campaignId: campaign.id,
      assignedUserIds: userIdsArray,
      updatedMessages: updateResult[0]
    };
  }
}

